    31	
    32	    public Javalin build() {
    33	        Javalin app = Javalin.create();
    34	        app.get("/rooms", ctx -> respond(ctx, 200, reservations.rooms()));
    35	        app.post("/reservations", ctx -> respond(ctx, 201, reservations.create(parseCreate(ctx.body()))));
    36	        app.get("/reservations/{id}", ctx -> respond(ctx, 200, reservations.get(ctx.pathParam("id"))));
    37	        app.post("/reservations/{id}/confirmation", ctx -> respond(ctx, 200, reservations.confirm(ctx.pathParam("id"))));
    38	        app.post("/reservations/{id}/cancellation", ctx -> respond(ctx, 200, reservations.cancel(ctx.pathParam("id"))));
    39	        app.post("/reservations/{id}/check-in", ctx -> respond(ctx, 200, reservations.checkIn(ctx.pathParam("id"))));
    40	        app.post("/reservations/{id}/check-out", ctx -> respond(ctx, 200, reservations.checkOut(ctx.pathParam("id"))));
    41	        app.get("/reservations/{id}/document", ctx -> respond(ctx, 200, reservations.document(ctx.pathParam("id"))));
    42	        app.get("/messages", ctx -> respond(ctx, 200, reservations.messages()));
    43	        app.get("/reports/occupancy", ctx -> csv(ctx, reports.occupancy(
    44	                parseDate(ctx.queryParam("date"), "date"))));
    45	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(parseMonth(ctx.queryParam("month")))));
    46	        app.exception(ApiException.class, (e, ctx) ->
    47	                respond(ctx, e.status(), Map.of("error", e.code(), "message", e.getMessage())));
    48	        app.exception(Exception.class, (e, ctx) -> {
    49	            e.printStackTrace();
    50	            respond(ctx, 500, Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    51	        });
    52	        return app;
    53	    }
    54	
    55	    private void respond(Context ctx, int status, Object body) {
    56	        try {
    57	            ctx.status(status).contentType("application/json").result(json.writeValueAsString(body));
    58	        } catch (JsonProcessingException e) {
    59	            throw new IllegalStateException(e);
    60	        }
    61	    }
    62	
    63	    private void csv(Context ctx, String body) {
    64	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
    65	    }
    66	
    67	    private CreateReservation parseCreate(String body) {
    68	        JsonNode root;
    69	        try {
    70	            root = json.readTree(body);
    71	        } catch (JsonProcessingException e) {
    72	            throw ApiException.invalidRequest("O corpo não é um JSON válido");
    73	        }
    74	        if (root == null || !root.isObject()) {
    75	            throw ApiException.invalidRequest("O corpo deve ser um objeto JSON");
    76	        }
    77	        JsonNode company = root.get("companyCode");
    78	        return new CreateReservation(
    79	                integer(root, "roomNumber"), text(root, "guestName"), text(root, "guestEmail"),
    80	                text(root, "guestCpf"), parseDate(text(root, "checkIn"), "checkIn"),
    81	                parseDate(text(root, "checkOut"), "checkOut"), integer(root, "guests"),
    82	                text(root, "ratePlan"), company != null && company.isTextual() ? company.asText() : null);
    83	    }
    84	
    85	    private static String text(JsonNode root, String field) {
    86	        JsonNode node = root.get(field);
    87	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    88	            throw ApiException.invalidRequest("Campo ausente ou inválido: " + field);
    89	        }
    90	        return node.asText();
    91	    }
    92	
    93	    private static int integer(JsonNode root, String field) {
    94	        JsonNode node = root.get(field);
    95	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    96	            throw ApiException.invalidRequest("Campo ausente ou inválido: " + field);
    97	        }
    98	        return node.asInt();
    99	    }
