   102	        try {
   103	            if (value == null) throw new DateTimeParseException("ausente", "", 0);
   104	            return LocalDate.parse(value);
   105	        } catch (DateTimeParseException e) {
   106	            throw ApiException.invalidRequest("Data inválida em " + field + ", use AAAA-MM-DD");
   107	        }
   108	    }
   109	
   110	    private static YearMonth parseMonth(String value) {
   111	        try {
   112	            if (value == null) throw new DateTimeParseException("ausente", "", 0);
