     8	import pousada.persistence.RoomRepository;
     9	
    10	import java.math.BigDecimal;
    11	import java.time.LocalDate;
    12	import java.time.YearMonth;
    13	import java.util.List;
    14	import java.util.Map;
    15	import java.util.function.Function;
    16	import java.util.stream.Collectors;
    17	
    18	public class ReportService {
    19	    private final Database database;
    20	    private final RoomRepository rooms;
    21	    private final ReservationRepository reservations;
    22	
    23	    public ReportService(Database database, RoomRepository rooms, ReservationRepository reservations) {
    24	        this.database = database;
    25	        this.rooms = rooms;
    26	        this.reservations = reservations;
    27	    }
    28	
    29	    public String occupancy(LocalDate night) {
    30	        return database.inTransaction(c -> {
    31	            List<Room> allRooms = rooms.findAll(c);
    32	            Map<Integer, Room> byNumber = allRooms.stream().collect(Collectors.toMap(Room::number, Function.identity()));
    33	            List<Reservation> occupying = reservations.findPaidOnNight(c, night);
    34	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    35	            for (Reservation r : occupying) {
    36	                csv.append(r.roomNumber()).append(',').append(byNumber.get(r.roomNumber()).type()).append(',')
    37	                        .append(r.id()).append(',').append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    38	            }
    39	            long occupiedRooms = occupying.stream().map(Reservation::roomNumber).distinct().count();
    40	            return csv.append("total,").append(occupiedRooms).append('/').append(allRooms.size()).append('\n').toString();
    41	        });
    42	    }
    43	
    44	    public String revenue(YearMonth month) {
    45	        return database.inTransaction(c -> {
    46	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    47	            BigDecimal total = Money.ZERO;
    48	            for (Reservation r : reservations.findStartingIn(c, month)) {
    49	                BigDecimal kept = r.amountKept();
    50	                if (kept.signum() <= 0) continue;
    51	                csv.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
    52	                        .append(r.checkOut()).append(',').append(r.status()).append(',').append(kept).append('\n');
    53	                total = total.add(kept);
    54	            }
    55	            return csv.append("total,").append(Money.round(total)).append('\n').toString();
    56	        });
    57	    }
    58	}
