     1	package pousada.service;
     2	
     3	import pousada.domain.*;
     4	import pousada.persistence.Database;
     5	import pousada.persistence.MessageRepository;
     6	import pousada.persistence.ReservationRepository;
     7	import pousada.persistence.RoomRepository;
     8	
     9	import java.sql.Connection;
    10	import java.util.List;
    11	import java.util.function.UnaryOperator;
    12	
    13	public class ReservationService {
    14	    private final Database database;
    15	    private final RoomRepository rooms;
    16	    private final ReservationRepository reservations;
    17	    private final MessageRepository messages;
    18	    private final RatePlanCatalog plans;
    19	
    20	    public ReservationService(Database database, RoomRepository rooms, ReservationRepository reservations,
    21	                              MessageRepository messages, RatePlanCatalog plans) {
    22	        this.database = database;
    23	        this.rooms = rooms;
    24	        this.reservations = reservations;
    25	        this.messages = messages;
    26	        this.plans = plans;
    27	    }
    28	
    29	    public List<Room> rooms() {
    30	        return database.inTransaction(rooms::findAll);
    31	    }
    32	
    33	    public List<Message> messages() {
    34	        return database.inTransaction(messages::findAll);
    35	    }
    36	
    37	    public Reservation get(String id) {
    38	        return database.inTransaction(c -> reservations.find(c, parseId(id))
    39	                .orElseThrow(() -> ApiException.reservationNotFound(id)));
    40	    }
    41	
    42	    public Receipt document(String id) {
    43	        return database.inTransaction(c -> {
    44	            Reservation reservation = reservations.find(c, parseId(id))
    45	                    .orElseThrow(() -> ApiException.reservationNotFound(id)).requirePaid();
    46	            return receiptOf(c, reservation);
    47	        });
    48	    }
    49	
    50	    public Reservation create(CreateReservation request) {
    51	        if (!request.checkOut().isAfter(request.checkIn())) {
    52	            throw ApiException.invalidRequest("A saída deve ser depois da entrada");
    53	        }
    54	        if (request.guests() < 1) {
    55	            throw ApiException.invalidRequest("É preciso ao menos um hóspede");
    56	        }
    57	        RatePlan plan = plans.find(request.ratePlan())
    58	                .orElseThrow(() -> ApiException.invalidRequest("Plano de tarifa desconhecido: " + request.ratePlan()));
    59	        return database.inTransaction(c -> {
    60	            Room room = rooms.findForUpdate(c, request.roomNumber())
    61	                    .orElseThrow(() -> ApiException.roomNotFound(request.roomNumber()));
    62	            if (request.guests() > room.capacity()) {
    63	                throw ApiException.capacityExceeded(room.capacity());
    64	            }
    65	            Booking booking = new Booking(room, request.checkIn(), request.checkOut(), request.guests(),
    66	                    request.companyCode());
    67	            plan.validate(booking);
    68	            if (reservations.hasOverlap(c, room.number(), request.checkIn(), request.checkOut())) {
    69	                throw ApiException.roomUnavailable();
    70	            }
    71	            Quote quote = plan.quote(booking);
    72	            return reservations.insert(c, new Reservation(0, room.number(), request.guestName(),
    73	                    request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    74	                    request.guests(), plan.code(), booking.nights(), quote.subtotal(), quote.discount(),
    75	                    quote.total(), ReservationStatus.PENDING, Money.ZERO, null));
    76	        });
    77	    }
    78	
    79	    public Reservation confirm(String id) {
    80	        return database.inTransaction(c -> {
    81	            Reservation confirmed = transition(c, id, Reservation::confirm);
    82	            messages.insert(c, Message.confirmation(confirmed, receiptOf(c, confirmed)));
    83	            return confirmed;
    84	        });
    85	    }
    86	
    87	    public Reservation cancel(String id) {
    88	        return database.inTransaction(c -> transition(c, id, r -> r.cancel(planOf(r))));
    89	    }
    90	
    91	    public Reservation checkIn(String id) {
    92	        return database.inTransaction(c -> transition(c, id, Reservation::checkInGuest));
    93	    }
    94	
    95	    public Receipt checkOut(String id) {
    96	        return database.inTransaction(c -> receiptOf(c, transition(c, id, Reservation::checkOutGuest)));
    97	    }
    98	
    99	    private Reservation transition(Connection c, String id, UnaryOperator<Reservation> change) {
   100	        Reservation current = reservations.findForUpdate(c, parseId(id))
   101	                .orElseThrow(() -> ApiException.reservationNotFound(id));
   102	        Reservation updated = change.apply(current);
   103	        reservations.updateState(c, updated);
   104	        return updated;
   105	    }
   106	
   107	    private RatePlan planOf(Reservation reservation) {
   108	        return plans.find(reservation.ratePlan()).orElseThrow();
   109	    }
   110	
   111	    private Receipt receiptOf(Connection c, Reservation reservation) {
   112	        return Receipt.of(reservation, rooms.find(c, reservation.roomNumber()).orElseThrow());
   113	    }
   114	
   115	    private long parseId(String id) {
   116	        try {
   117	            return Long.parseLong(id);
   118	        } catch (NumberFormatException e) {
   119	            throw ApiException.reservationNotFound(id);
   120	        }
   121	    }
   122	}

