     8	
     9	public class Database {
    10	    private final String url;
    11	    private final String user;
    12	    private final String password;
    13	
    14	    public Database(String url, String user, String password) {
    15	        this.url = url;
    16	        this.user = user;
    17	        this.password = password;
    18	    }
    19	
    20	    public <T> T inTransaction(Function<Connection, T> work) {
    21	        try (Connection connection = DriverManager.getConnection(url, user, password)) {
    22	            connection.setAutoCommit(false);
    23	            try {
    24	                T result = work.apply(connection);
    25	                connection.commit();
    26	                return result;
    27	            } catch (RuntimeException e) {
    28	                connection.rollback();
    29	                throw e;
    30	            }
    31	        } catch (SQLException e) {
    32	            throw new IllegalStateException(e);
    33	        }
    34	    }
    35	
    36	    /** Cria o que falta no banco; espera o banco subir se preciso. */
    37	    public void initialize() {
    38	        for (int attempt = 1; ; attempt++) {
    39	            try {
    40	                inTransaction(c -> {
    41	                    try (Statement s = c.createStatement()) {
    42	                        s.execute("SELECT pg_advisory_xact_lock(7070)");
    43	                        s.execute("""
    44	                                CREATE TABLE IF NOT EXISTS rooms (
    45	                                  number INTEGER PRIMARY KEY,
    46	                                  type TEXT NOT NULL,
    47	                                  capacity INTEGER NOT NULL,
    48	                                  nightly_rate NUMERIC(12,2) NOT NULL)""");
    49	                        s.execute("""
    50	                                CREATE TABLE IF NOT EXISTS reservations (
    51	                                  id BIGSERIAL PRIMARY KEY,
    52	                                  room_number INTEGER NOT NULL REFERENCES rooms(number),
    53	                                  guest_name TEXT NOT NULL,
    54	                                  guest_email TEXT NOT NULL,
    55	                                  guest_cpf TEXT NOT NULL,
    56	                                  check_in DATE NOT NULL,
    57	                                  check_out DATE NOT NULL,
    58	                                  guests INTEGER NOT NULL,
    59	                                  rate_plan TEXT NOT NULL,
    60	                                  nights INTEGER NOT NULL,
    61	                                  subtotal NUMERIC(12,2) NOT NULL,
    62	                                  discount NUMERIC(12,2) NOT NULL,
    63	                                  total NUMERIC(12,2) NOT NULL,
    64	                                  status TEXT NOT NULL,
    65	                                  amount_paid NUMERIC(12,2) NOT NULL,
    66	                                  refund NUMERIC(12,2))""");
    67	                        s.execute("""
    68	                                CREATE TABLE IF NOT EXISTS messages (
    69	                                  id BIGSERIAL PRIMARY KEY,
    70	                                  channel TEXT NOT NULL,
    71	                                  recipient TEXT NOT NULL,
    72	                                  subject TEXT NOT NULL,
    73	                                  body TEXT NOT NULL)""");
    74	                        s.execute("""
    75	                                INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES
    76	                                  (101, 'STANDARD', 2, 249.90), (102, 'STANDARD', 2, 249.90),
    77	                                  (201, 'DELUXE', 3, 389.90), (202, 'DELUXE', 3, 389.90),
    78	                                  (301, 'SUITE', 4, 579.90)
    79	                                ON CONFLICT (number) DO NOTHING""");
    80	                    } catch (SQLException e) {
    81	                        throw new IllegalStateException(e);
    82	                    }
    83	                    return null;
    84	                });
    85	                return;
    86	            } catch (IllegalStateException e) {
    87	                if (attempt >= 30) throw e;
    88	                try {
    89	                    Thread.sleep(2000);
    90	                } catch (InterruptedException ie) {
    91	                    Thread.currentThread().interrupt();
    92	                    throw e;
    93	                }
    94	            }
    95	        }
    96	    }
    97	}
