    19	
    20	    public Reservation insert(Connection c, Reservation r) {
    21	        return Sql.unchecked(() -> {
    22	            try (PreparedStatement ps = c.prepareStatement("""
    23	                    INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
    24	                      guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund)
    25	                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", Statement.RETURN_GENERATED_KEYS)) {
    26	                ps.setInt(1, r.roomNumber());
    27	                ps.setString(2, r.guestName());
    28	                ps.setString(3, r.guestEmail());
    29	                ps.setString(4, r.guestCpf());
    30	                ps.setObject(5, r.checkIn());
    31	                ps.setObject(6, r.checkOut());
    32	                ps.setInt(7, r.guests());
    33	                ps.setString(8, r.ratePlan());
    34	                ps.setInt(9, r.nights());
    35	                ps.setBigDecimal(10, r.subtotal());
    36	                ps.setBigDecimal(11, r.discount());
    37	                ps.setBigDecimal(12, r.total());
    38	                ps.setString(13, r.status().name());
    39	                ps.setBigDecimal(14, r.amountPaid());
    40	                ps.setBigDecimal(15, r.refund());
    41	                ps.executeUpdate();
    42	                try (ResultSet keys = ps.getGeneratedKeys()) {
    43	                    keys.next();
    44	                    return find(c, keys.getLong("id")).orElseThrow();
    45	                }
    46	            }
    47	        });
    48	    }
    49	
    50	    public void updateState(Connection c, Reservation r) {
    51	        Sql.unchecked(() -> {
    52	            try (PreparedStatement ps = c.prepareStatement(
    53	                    "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    54	                ps.setString(1, r.status().name());
    55	                ps.setBigDecimal(2, r.amountPaid());
    56	                ps.setBigDecimal(3, r.refund());
    57	                ps.setLong(4, r.id());
    58	                ps.executeUpdate();
    59	                return null;
    60	            }
    61	        });
    62	    }
    63	
    64	    public Optional<Reservation> find(Connection c, long id) {
    65	        return one(c, SELECT + "WHERE id = ?", id);
    66	    }
    67	
    68	    public Optional<Reservation> findForUpdate(Connection c, long id) {
