    71	
    72	    /** Há reserva não cancelada do quarto que cruze alguma noite de [checkIn, checkOut)? */
    73	    public boolean hasOverlap(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    74	        return Sql.unchecked(() -> {
    75	            try (PreparedStatement ps = c.prepareStatement("""
    76	                    SELECT 1 FROM reservations
    77	                    WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?""")) {
    78	                ps.setInt(1, roomNumber);
    79	                ps.setObject(2, checkOut);
    80	                ps.setObject(3, checkIn);
    81	                try (ResultSet rs = ps.executeQuery()) {
    82	                    return rs.next();
    83	                }
    84	            }
    85	        });
    86	    }
