    88	    /** Reservas pagas que ocupam o quarto na noite informada, por número de quarto. */
    89	    public List<Reservation> findPaidOnNight(Connection c, LocalDate night) {
    90	        return list(c, SELECT + "WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
    91	                + "AND check_in <= ? AND check_out > ? ORDER BY room_number, id", night, night);
