    99	    private Optional<Reservation> one(Connection c, String sql, Object param) {
   100	        List<Reservation> found = list(c, sql, param);
   101	        return found.isEmpty() ? Optional.empty() : Optional.of(found.get(0));
   102	    }
   103	
   104	    private List<Reservation> list(Connection c, String sql, Object... params) {
   105	        return Sql.unchecked(() -> {
   106	            try (PreparedStatement ps = c.prepareStatement(sql)) {
   107	                for (int i = 0; i < params.length; i++) ps.setObject(i + 1, params[i]);
   108	                try (ResultSet rs = ps.executeQuery()) {
   109	                    List<Reservation> result = new ArrayList<>();
   110	                    while (rs.next()) result.add(map(rs));
   111	                    return result;
   112	                }
   113	            }
   114	        });
