    10	
    11	    public WeekendPackagePlan(Map<RoomType, BigDecimal> priceByType) {
    12	        this.priceByType = Map.copyOf(priceByType);
    13	    }
    14	
    15	    @Override public String code() { return "WEEKEND_PACKAGE"; }
    16	
    17	    @Override
    18	    public void validate(Booking booking) {
    19	        boolean fridayToSunday = booking.checkIn().getDayOfWeek() == DayOfWeek.FRIDAY
    20	                && booking.checkOut().equals(booking.checkIn().plusDays(2));
    21	        if (!fridayToSunday) {
    22	            throw ApiException.invalidRequest("O WEEKEND_PACKAGE exige entrada na sexta e saída no domingo seguinte");
    23	        }
    24	    }
    25	
    26	    @Override
    27	    public Quote quote(Booking booking) {
    28	        return new Quote(Money.round(priceByType.get(booking.room().type())), Money.ZERO);
    29	    }
