     3	import org.junit.jupiter.api.Test;
     4	
     5	import java.math.BigDecimal;
     6	import java.time.LocalDate;
     7	import java.util.Map;
     8	
     9	import static org.junit.jupiter.api.Assertions.*;
    10	
    11	class RatePlanTest {
    12	    private final Room standard = new Room(101, RoomType.STANDARD, 2, Money.of("249.90"));
    13	    private final Room deluxe = new Room(201, RoomType.DELUXE, 3, Money.of("389.90"));
    14	    private final CorporatePlan corporate = new CorporatePlan(Map.of("TECNOSUL", Money.percent(12)));
    15	    private final WeekendPackagePlan weekend = new WeekendPackagePlan(Map.of(RoomType.DELUXE, Money.of("820.00")));
    16	
    17	    private Booking booking(Room room, String in, String out, String company) {
    18	        return new Booking(room, LocalDate.parse(in), LocalDate.parse(out), 2, company);
    19	    }
    20	
    21	    @Test
    22	    void highSeasonNights() {
    23	        Quote q = new StandardPlan().quote(booking(standard, "2027-07-10", "2027-07-12", null));
    24	        assertEquals(Money.of("599.76"), q.subtotal());
    25	        assertEquals(Money.of("599.76"), q.total());
    26	    }
    27	
    28	    @Test
    29	    void nonRefundableGivesNothingBack() {
    30	        assertEquals(Money.ZERO, new NonRefundablePlan().refund(Money.of("100")));
    31	    }
    32	
    33	    @Test
    34	    void corporate() {
    35	        Quote q = corporate.quote(booking(deluxe, "2027-03-10", "2027-03-12", "TECNOSUL"));
    36	        assertEquals(Money.of("779.80"), q.subtotal());
    37	        assertEquals(Money.of("93.58"), q.discount());
    38	        assertEquals(Money.of("686.22"), q.total());
    39	        assertThrows(ApiException.class, () -> corporate.validate(booking(deluxe, "2027-03-10", "2027-03-12", null)));
    40	        assertThrows(ApiException.class, () -> corporate.validate(booking(deluxe, "2027-03-10", "2027-03-12", "X")));
    41	    }
    42	
    43	    @Test
    44	    void weekendPackage() {
    45	        Booking ok = booking(deluxe, "2027-03-12", "2027-03-14", null);
    46	        weekend.validate(ok);
    47	        assertEquals(Money.of("820.00"), weekend.quote(ok).total());
    48	        assertEquals(Money.of("410.00"), weekend.refund(Money.of("820.00")));
    49	        assertThrows(ApiException.class, () -> weekend.validate(booking(deluxe, "2027-03-13", "2027-03-15", null)));
    50	        assertThrows(ApiException.class, () -> weekend.validate(booking(deluxe, "2027-03-12", "2027-03-15", null)));
    51	    }
    52	
    53	    @Test
    54	    void longStay() {
    55	        LongStayPlan plan = new LongStayPlan();
    56	        Booking b = booking(standard, "2027-03-01", "2027-03-08", null);
    57	        plan.validate(b);
    58	        Quote q = plan.quote(b);
    59	        assertEquals(Money.of("1749.30"), q.subtotal());
    60	        assertEquals(Money.of("174.93"), q.discount());
    61	        assertEquals(Money.of("1574.37"), q.total());
    62	        assertThrows(ApiException.class, () -> plan.validate(booking(standard, "2027-03-01", "2027-03-07", null)));
    63	    }
    64	
    65	    @Test
    66	    void receiptText() {
    67	        Reservation r = new Reservation(7, 201, "Carla Dias", "c@x.com", "111.222.333-44",
    68	                LocalDate.parse("2027-03-10"), LocalDate.parse("2027-03-12"), 2, "STANDARD", 2,
    69	                Money.of("779.80"), Money.ZERO, Money.of("779.80"), ReservationStatus.CONFIRMED,
    70	                Money.of("779.80"), null);
    71	        assertEquals("""
    72	                Comprovante de reserva nº 7
    73	                Hóspede: Carla Dias (CPF 111.222.333-44)
    74	                Quarto: 201 (DELUXE)
    75	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
    76	                Diárias: R$ 779,80
    77	                Total: R$ 779,80""", Receipt.of(r, deluxe).toText());
    78	        assertEquals("R$ 1.234,56", Money.format(new BigDecimal("1234.56")));
    79	    }
    80	}
